BEGIN;
SET LOCAL lock_timeout='5s'; SET LOCAL statement_timeout='60s';
LOCK TABLE public.questions IN SHARE ROW EXCLUSIVE MODE;
CREATE TEMP TABLE swsi_before ON COMMIT DROP AS SELECT id, to_jsonb(q) AS row FROM public.questions q;
CREATE TEMP TABLE swsi_batch(id text primary key, status text, note text, url text) ON COMMIT DROP;
INSERT INTO swsi_batch VALUES ('SP-115-2-037','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考國民年金法第40條（配偶請領遺屬年金給付應年滿五十五歲且婚姻關係存續一年以上），最後修正公布日：第40條 2020-06-03，本題考試日 2026-07-25 之後未再修正，考試時條文與現行條文相同，官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0050152'),('SP104-1-32','changed',$swsi$考試時點法規核對（逐條人工核對）：本題考試日 2015-02-07。本題考國民年金法第32條之1（生育給付）。考試時規定分娩或早產者，按其月投保金額一次發給一個月生育給付，雙生以上比例增給，同時符合相關社會保險生育給付或補助條件者僅得擇一請領；2015-12-16 修正為一次發給二個月生育給付。依現行條文，選項(A)「分娩者一次發給1個月生育給付」亦屬錯誤，選項(B)仍錯誤。本題官方答案依考試時條文判定；作答時請以現行條文為準。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0050152'),('SP104-2-11','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考國民年金法第30條（不得選擇第一款計給方式、僅得按月投保金額乘以保險年資再乘以百分之一點三計給之情形），最後修正公布日：第30條 2011-06-29，本題考試日 2015-07-25 之後未再修正，考試時條文與現行條文相同，官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0050152'),('SP104-2-35','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考試日 2015-07-25。本題考國民年金法第12條（保險費負擔比例）。第12條於 2020-06-03 修正，增列符合社會救助法規定之中低收入戶被保險人之保險費負擔（自付百分之三十），輕度身心障礙者自付百分之四十五、中央主管機關負擔百分之二十七點五、直轄市或縣（市）主管機關負擔百分之二十七點五之規定未變，選項(B)仍正確。官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0050152'),('SP106-2-23','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考國民年金法第2條（保險事故分為老年、生育、身心障礙及死亡四種），最後修正公布日：第2條 2011-06-29，本題考試日 2017-07-29 之後未再修正，考試時條文與現行條文相同，官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0050152'),('SP106-2-24','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考國民年金法第47條（中央主管機關應補助保險費及應負擔款項之籌措來源），最後修正公布日：第47條 2007-08-08，本題考試日 2017-07-29 之後未再修正，考試時條文與現行條文相同，官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0050152'),('SP106-2-32','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考國民年金法第10條（保險基金餘額足以支付未來二十年保險給付時不予調高保險費率），最後修正公布日：第10條 2007-08-08，本題考試日 2017-07-29 之後未再修正，考試時條文與現行條文相同，官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0050152'),('SP106-2-33','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考試日 2017-07-29。本題考國民年金法第12條（保險費負擔比例）。第12條於 2020-06-03 修正，增列符合社會救助法規定之中低收入戶被保險人之保險費負擔（自付百分之三十），輕度身心障礙者自付百分之四十五、中央主管機關負擔百分之二十七點五、直轄市或縣（市）主管機關負擔百分之二十七點五之規定未變，選項(C)仍正確。官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0050152'),('SP107-1-26','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考國民年金法第5條（爭議事項應於收到核定通知文件之翌日起六十日內先申請審議），最後修正公布日：第5條 2007-08-08，本題考試日 2018-02-03 之後未再修正，考試時條文與現行條文相同，官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0050152'),('SP107-1-39','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考國民年金法第46條（人事及行政管理經費以當年度應收保險費總額百分之三點五為上限），最後修正公布日：第46條 2007-08-08，本題考試日 2018-02-03 之後未再修正，考試時條文與現行條文相同，官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0050152'),('SP108-1-32','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考國民年金法第17條（逾十年之欠繳保險費不得請求補繳），最後修正公布日：第17條 2007-08-08，本題考試日 2019-01-19 之後未再修正，考試時條文與現行條文相同，官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0050152'),('SP109-1-36','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考國民年金法第13條、第20條、第25條、第26條（保險費繳納後不予退還及溢繳誤繳之例外、同一給付不得重複請領、減領保險給付一年以一次為限、故意造成保險事故除喪葬給付外不予給付），最後修正公布日：第13條 2011-12-28、第20條 2007-08-08、第25條 2007-08-08、第26條 2007-08-08，本題考試日 2020-02-15 之後未再修正，考試時條文與現行條文相同，官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0050152'),('SP109-2-38','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考國民年金法第2條（保險給付為老年年金、生育、身心障礙年金、喪葬及遺屬年金給付），最後修正公布日：第2條 2011-06-29，本題考試日 2020-08-01 之後未再修正，考試時條文與現行條文相同，官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0050152'),('SP110-1-37','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考國民年金法第11條（月投保金額依消費者物價指數累計成長率調整），最後修正公布日：第11條 2007-08-08，本題考試日 2021-02-06 之後未再修正，考試時條文與現行條文相同，官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0050152'),('SP110-2-37','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考國民年金法第20條、第25條、第26條、第28條（同一給付不得重複請領、得申請減領保險給付、故意犯罪行為除未涉案之當序受益人外不予給付、請求權五年），最後修正公布日：第20條 2007-08-08、第25條 2007-08-08、第26條 2007-08-08、第28條 2007-08-08，本題考試日 2021-08-21 之後未再修正，考試時條文與現行條文相同，官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0050152'),('SP112-1-19','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考國民年金法第10條、第11條（保險費依定額之月投保金額乘以保險費率計算，月投保金額依消費者物價指數調整，屬定額保費制），最後修正公布日：第10條 2007-08-08、第11條 2007-08-08，本題考試日 2023-02-18 之後未再修正，考試時條文與現行條文相同，官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0050152'),('SP115-1-36','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考國民年金法第1條、第2條、第3條（立法目的、四種保險事故及給付種類、中央主管機關為中央社政主管機關），最後修正公布日：第1條 2011-06-29、第2條 2011-06-29、第3條 2007-08-08，本題考試日 2026-02-07 之後未再修正，考試時條文與現行條文相同，官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0050152');
DO $g$ BEGIN
IF (SELECT count(*) FROM swsi_before)<>4800 THEN RAISE EXCEPTION 'count'; END IF;
IF (SELECT count(*) FROM swsi_batch)<>17 THEN RAISE EXCEPTION 'batch size'; END IF;
IF (SELECT count(*) FROM public.questions q JOIN swsi_batch b USING(id) WHERE q.legal_status='unreviewed' AND q.legal_checked_at IS NULL AND q.legal_note IS NULL AND q.legal_source_url IS NULL)<>17 THEN RAISE EXCEPTION 'preimage mismatch'; END IF;
END $g$;
UPDATE public.questions q SET legal_status=b.status, legal_checked_at='2026-11-25T12:00:00+00:00'::timestamptz, legal_note=b.note, legal_source_url=b.url
FROM swsi_batch b WHERE q.id=b.id;
DO $a$ BEGIN
IF (SELECT md5(string_agg(concat_ws(chr(31),q.id,q.legal_status,q.legal_note,q.legal_source_url),chr(30) ORDER BY q.id)) FROM public.questions q JOIN swsi_batch b USING(id) WHERE q.legal_checked_at='2026-11-25T12:00:00+00:00'::timestamptz)<>'c312af31c013aaaf24d6d580b11024ab' THEN RAISE EXCEPTION 'postimage mismatch'; END IF;
IF EXISTS (SELECT 1 FROM swsi_before b FULL JOIN public.questions q USING(id) WHERE coalesce(b.id,q.id) NOT IN (SELECT id FROM swsi_batch) AND b.row IS DISTINCT FROM to_jsonb(q)) THEN RAISE EXCEPTION 'unrelated change'; END IF;
IF EXISTS (SELECT 1 FROM swsi_before b JOIN public.questions q USING(id) WHERE b.id IN (SELECT id FROM swsi_batch) AND (b.row - 'legal_status' - 'legal_checked_at' - 'legal_note' - 'legal_source_url') IS DISTINCT FROM (to_jsonb(q) - 'legal_status' - 'legal_checked_at' - 'legal_note' - 'legal_source_url')) THEN RAISE EXCEPTION 'non-legal field changed'; END IF;
END $a$;
SELECT count(*) FILTER (WHERE q.legal_status='verified_current') verified_16, count(*) FILTER (WHERE q.legal_status='changed') changed_1, count(*) total_17 FROM public.questions q JOIN swsi_batch b USING(id);
COMMIT;
